-- IPA 2020-12-13 FE exemption examination. Additive attributed adaptations.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2020-20201213-q51','exam-fe','EVM','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問51・改編】プロジェクト進捗管理で、ある時点のEV−PVが負であることは何を意味するか。','[{"id":"a","text":"計画よりスケジュール効率が良い"},{"id":"b","text":"必ず計画より完了が遅れる"},{"id":"c","text":"計画より進捗が遅れている"},{"id":"d","text":"計画より進捗が進んでいる"}]','"c"','EV−PVはスケジュール差異で、負ならその時点の出来高は計画値に達していない。完了時期が必ず遅れるとまでは断定できない。 中文解析：EV减PV为负表示当前完成价值低于计划价值，即目前进度落后，但不代表最终一定延期。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q54','exam-fe','パレート図','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問54・改編】品質問題の原因を図で分析した結果、問題の80%以上が少数の原因に集中していると分かった。この分析に用いた図はどれか。','[{"id":"a","text":"管理図"},{"id":"b","text":"散布図"},{"id":"c","text":"特性要因図"},{"id":"d","text":"パレート図"}]','"d"','パレート図は原因別の件数を多い順の棒グラフと累積比率で表し、重点的に対処すべき原因を見つける。 中文解析：帕累托图将各原因按数量排序并显示累计比例，便于找出主要原因。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q55','exam-fe','システム移行計画','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問55・改編】システムの移行計画について適切な記述はどれか。','[{"id":"a","text":"移行失敗時に旧システムへ戻す判断基準を計画書に含める"},{"id":"b","text":"データが多いほど切替え直前に一括移行すべきである"},{"id":"c","text":"新旧システムの環境を一部共有すると移行確認が容易になる"},{"id":"d","text":"新旧システムを並行運用すると移行費用が低減する"}]','"a"','移行失敗時の切戻し条件を事前に定めることで、適切な判断と復旧が可能になる。並行運用には追加費用が生じる。 中文解析：迁移计划应预先规定失败时的回退判断标准；并行运行通常还会增加成本。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q60','exam-fe','事業継続計画','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問60・改編】事業継続計画（BCP）の監査において、適切と判断される状況はどれか。','[{"id":"a","text":"従業員の緊急連絡先リストを作成し最新版に更新している"},{"id":"b","text":"重要書類を複製せず一か所に集中保管している"},{"id":"c","text":"全業務に優先順位を設けず同一水準でBCPを策定している"},{"id":"d","text":"平常時はBCPを従業員に公開しない"}]','"a"','緊急連絡先を最新に保つことは災害時の連絡に役立つ。BCPは重要業務の優先順位、情報の保全、周知を考慮する。 中文解析：持续更新紧急联系名单有助于灾害时联络；BCP还应考虑业务优先级、资料保护和员工知晓。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2020-20201213-q69','exam-fe','EMS','standard','single_choice','【IPA 2020年度 修了認定試験 2020-12-13 問69・改編】EMS（Electronics Manufacturing Services）の説明として適切なものはどれか。','[{"id":"a","text":"消費者から家電製品の問合せを電話で受ける"},{"id":"b","text":"製造設備を持たず製品の企画・設計・開発を行う"},{"id":"c","text":"他社から仕入れた電子機器の販売を専門に行う"},{"id":"d","text":"他社から受注した電子機器を受託生産する"}]','"d"','EMSは他社から電子機器の製造を受託するサービスである。製造設備を持たない企画・設計企業はファブレスに該当する。 中文解析：EMS接受其他企业委托生产电子设备；不自有工厂而负责设计等业务属于无晶圆厂或无工厂模式。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20201213_FE.pdf','ja','A','explicit','standard','fe_exemption');
